{{--
    GIFT BOX POPUPS -- the CSS (Lane GBX). Printed inside the box's own <style>
    ONLY while Marketing -> Free gifts -> Overview -> Gift box popups resolves
    on for this request; off, this file is never reached. Constants and the
    band count (an integer) only. Popovers are hidden by their own class and
    shown by :popover-open, so a browser without the Popover API keeps them
    hidden and its Gifts Criteria button is not drawn (@supports). No var()
    next to a newer CSS function; nothing measures. Only the chosen designs'
    rules are printed ($gbxPop, $gbxCrit, $gbxGlow), so the box stays light.
--}}.gbx.fgb-g5 .fgb-th{grid-template-columns:repeat(5,minmax(0,1fr))}.gbx.fgb-g4 .fgb-th{grid-template-columns:repeat(4,minmax(0,1fr))}.gbx .fgb-th button.fgb-t{padding:0;margin:0;font:inherit;color:inherit;cursor:pointer;border:1px solid rgba(42,34,40,.08);background:#fff;-webkit-appearance:none;appearance:none}.gbx .fgb-th button.fgb-t:focus-visible,.gbx .gbx-cr:focus-visible{outline:2px solid #C6395F;outline-offset:2px}.gbx .gbx-ft{grid-column:1/-1;flex-basis:100%;display:flex;align-items:center;justify-content:space-between;gap:10px;min-width:0}.gbx .gbx-ft .fgb-tg{flex:0 1 auto;margin:0;min-height:32px}.gbx .fgb-ls .gbx-ft{margin-top:6px}.gbx .fgb-ls .gbx-ft .fgb-tg{margin:0;min-height:28px}.gbx .gbx-cr{display:inline-flex;align-items:center;gap:5px;border:1px solid rgba(46,143,98,.35);background:#f3faf6;color:#2e8f62;font:inherit;font-size:11.5px;font-weight:700;border-radius:999px;padding:0 11px;min-height:28px;cursor:pointer;white-space:nowrap}.gbx .gbx-cr svg{width:13px;height:13px;flex:none}@supports not selector(:popover-open){.gbx .gbx-cr{display:none}}
@if ($gbxGlow === 'G1').gbx-g1 .fgb-t{box-shadow:0 0 0 2px #fff,0 0 10px rgba(198,57,95,.28)}@endif
@if ($gbxGlow === 'G2').gbx-g2 .fgb-t{border-color:rgba(198,57,95,.55)!important;box-shadow:0 0 8px rgba(198,57,95,.22)}@endif
@if ($gbxGlow === 'G3').gbx-g3 .fgb-t{box-shadow:inset 0 0 0 2px #fff,0 0 0 1px rgba(198,57,95,.18),0 0 12px rgba(240,160,185,.5)}@endif
@if ($gbxGlow === 'G4').gbx-g4 .fgb-t{box-shadow:0 0 7px rgba(198,57,95,.18),0 0 15px rgba(214,181,140,.32)}@endif
.gbx-pp,.gbx-cp{display:none;position:fixed;inset:0;margin:auto;height:fit-content;max-height:none;border:0;padding:0;color:#221A20;background:#fff;font-family:inherit;font-size:14px;line-height:1.4;text-align:start;overflow:visible}.gbx-pp:popover-open{display:block}.gbx-pp::backdrop,.gbx-cp::backdrop{background:rgba(34,26,32,.45)}.gbx-x{position:absolute;top:10px;inset-inline-end:10px;width:36px;height:36px;display:grid;place-items:center;border:0;border-radius:50%;background:rgba(255,255,255,.92);color:#221A20;cursor:pointer;z-index:2;padding:0}.gbx-x:focus-visible{outline:2px solid rgba(198,57,95,.45);outline-offset:1px}.gbx-pp small,.gbx-k small{display:block;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#756C74}.gbx-pp h3{margin:3px 0 6px;font-size:16px;line-height:1.3;font-weight:700}.gbx-pr{margin:0;font-size:15px;display:flex;gap:8px;align-items:baseline;flex-wrap:wrap}.gbx-pr s{color:#756C74;font-size:13px}.gbx-pr b{color:#C13E63}.gbx-im{display:block;object-fit:contain;background:#FBF5F3}
@if ($gbxPop === 'A').gbx-pA{width:min(400px,calc(100vw - 32px));border-radius:16px;box-shadow:0 18px 50px rgba(34,26,32,.22)}.gbx-a{display:grid;grid-template-columns:112px minmax(0,1fr);gap:14px;padding:18px;align-items:center}.gbx-a .gbx-im{width:112px;height:112px;border-radius:12px}.gbx-a .gbx-tx{padding-inline-end:24px;min-width:0}.gbx-tag{display:inline-flex;align-items:center;gap:5px;margin-top:10px;font-size:11.5px;font-weight:700;color:#2e8f62;background:#f3faf6;border-radius:999px;padding:5px 10px}@endif
@if ($gbxPop === 'B').gbx-pB{width:min(340px,calc(100vw - 48px));border-radius:20px;overflow:hidden;box-shadow:0 22px 60px rgba(34,26,32,.25)}.gbx-b-ph{position:relative;margin:0;background:#fff;border-bottom:1px solid #f6e6ec}.gbx-b-ph .gbx-im{width:100%;height:auto;aspect-ratio:1;background:none;padding:22px;box-sizing:border-box}.gbx-badge{position:absolute;top:14px;inset-inline-start:14px;background:#C6395F;color:#fff;font-size:12px;font-weight:800;letter-spacing:.08em;padding:6px 12px;border-radius:999px}.gbx-b-tx{padding:16px 20px 20px;text-align:center}.gbx-b-tx .gbx-pr{justify-content:center}.gbx-note{display:flex;align-items:center;justify-content:center;gap:6px;margin:12px 0 0;padding-top:12px;border-top:1px dashed #f0d5de;font-size:12.5px;font-weight:700;color:#C6395F}@endif
@if ($gbxPop === 'D').gbx-pD{width:min(360px,calc(100vw - 48px));border-radius:4px;box-shadow:0 24px 70px rgba(34,26,32,.3)}.gbx-dd{padding:34px 28px 26px;text-align:center}.gbx-dd .gbx-im{width:180px;height:180px;margin:0 auto 18px;background:none}.gbx-dd small{letter-spacing:.22em;font-weight:600;color:#9b8a6e}.gbx-dd h3{font-size:17px;font-weight:500;margin:8px 0 12px}.gbx-dd .gbx-pr{justify-content:center;font-size:13px}.gbx-vl{color:#756C74;font-size:11px;letter-spacing:.14em;text-transform:uppercase}.gbx-fr{color:#221A20!important;letter-spacing:.18em;font-weight:800}.gbx-dl{margin:16px auto 0;padding-top:14px;border-top:1px solid #e6d8c2;max-width:220px;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#9b8a6e}.gbx-pD .gbx-x{background:none}@endif
@if ($gbxPop === 'C').gbx-k{grid-column:1/-1;flex-basis:100%;position:relative;display:grid;grid-template-columns:64px minmax(0,1fr) auto;gap:10px;align-items:center;margin:6px 0 2px;padding:10px 40px 10px 10px;border:1px solid #f0d5de;border-radius:12px;background:#FFF8FA;box-shadow:0 6px 18px rgba(198,57,95,.10);box-sizing:border-box;min-width:0}.gbx-k[hidden]{display:none}[dir=rtl] .gbx-k{padding:10px 10px 10px 40px}.gbx-k .gbx-im{width:64px;height:64px;border-radius:9px;background:#fff}.gbx-k small{font-size:10px}.gbx-k .gbx-nm{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:12.5px;line-height:1.3;margin:1px 0 3px;font-weight:700}.gbx-k .gbx-pr{font-size:13px;gap:6px}.gbx-k .gbx-pr s{font-size:11.5px}.gbx-kf{font-size:10.5px;font-weight:800;letter-spacing:.06em;color:#fff;background:#2e8f62;border-radius:999px;padding:4px 8px}.gbx-k .gbx-x{top:6px;inset-inline-end:6px;width:30px;height:30px;background:none;color:#756C74}.gbx-ka{position:absolute;top:-7px;width:12px;height:12px;background:#FFF8FA;border-top:1px solid #f0d5de;border-left:1px solid #f0d5de;transform:rotate(45deg);inset-inline-start:calc(var(--gi,0) * (var(--fg-pr,36px) * 1.17 + 5px) + var(--fg-pr,36px) * .5)}[dir=rtl] .gbx-ka{transform:rotate(45deg) scaleX(-1)}.fgb-g5 .gbx-ka{inset-inline-start:calc((var(--gi,0) + .5) * 20% - 6px)}.fgb-g4 .gbx-ka{inset-inline-start:calc((var(--gi,0) + .5) * 25% - 6px)}@endif
@if ($gbxBands > 0).gbx-cp{width:min(560px,calc(100vw - 48px));max-height:min(80vh,720px);border-radius:18px;box-shadow:0 22px 60px rgba(34,26,32,.25);flex-direction:column;overflow:hidden}.gbx-cp:popover-open{display:flex}.gbx-ch{position:relative;padding:18px 56px 12px 20px;border-bottom:1px solid #f1e8ec;background:linear-gradient(180deg,#FFF0F4,#fff)}[dir=rtl] .gbx-ch{padding:18px 20px 12px 56px}.gbx-ch h3{display:flex;align-items:center;gap:8px;margin:0;font-size:18px}.gbx-ch h3 svg{color:#2e8f62;width:18px;height:18px}.gbx-ch p{margin:4px 0 0;font-size:13px;color:#756C74}.gbx-cb{overflow:auto;overscroll-behavior:contain;padding:14px 16px 18px}.gbx-t{position:relative;display:inline-block;width:40px;height:40px;border-radius:9px;background:#fff;border:1px solid rgba(42,34,40,.1);flex:none}.gbx-t img{position:absolute;inset:8%;width:84%;height:84%;object-fit:contain}.gbx-t b{position:absolute;top:-6px;inset-inline-end:-6px;background:#2e8f62;color:#fff;font-size:9.5px;line-height:1;padding:3px 4px;border-radius:999px}.gbx-more{font-size:12px;font-weight:700;color:#756C74;align-self:center}.gbx-am{font-weight:800;color:#2e8f62;white-space:nowrap}.gbx-cn{font-size:12px;color:#756C74;white-space:nowrap}.gbx-you{font-size:11px;font-weight:800;color:#fff;background:#C6395F;border-radius:999px;padding:3px 9px;white-space:nowrap}@endif
@if ($gbxBands > 0 && $gbxCrit === '1').gbx-1{list-style:none;margin:0;padding:0;display:grid;gap:10px}.gbx-1 li{border:1px solid #ece4e8;border-radius:14px;padding:12px 14px;background:#fff}.gbx-1 li.on{border-color:#C6395F;box-shadow:0 0 0 3px #FFF0F4;background:#FFFBFC}.gbx-1h{display:flex;justify-content:space-between;align-items:center;gap:8px}.gbx-1 .gbx-am{font-size:15px}.gbx-1 .gbx-wd{margin:4px 0 9px;font-size:14px;font-weight:600}.gbx-1 .gbx-th{display:flex;gap:7px;flex-wrap:wrap;padding-top:4px}@endif
@if ($gbxBands > 0 && $gbxCrit === '2').gbx-2{list-style:none;margin:0;padding:0;position:relative}.gbx-2::before{content:"";position:absolute;top:18px;bottom:18px;inset-inline-start:13px;width:2px;background:#e6efe9}.gbx-2 li{position:relative;display:grid;grid-template-columns:28px 128px minmax(0,1fr) auto;gap:10px;align-items:center;padding:10px 0;border-bottom:1px dashed #efe6ea}.gbx-2 li:last-child{border-bottom:0}.gbx-dot{position:relative;z-index:1;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:800;background:#fff;border:2px solid #cfe3d7;color:#2e8f62;box-sizing:border-box}.gbx-2 li.done .gbx-dot{background:#e6f3ec}.gbx-2 li.on .gbx-dot{background:#C6395F;border-color:#C6395F;color:#fff;box-shadow:0 0 0 4px #FFF0F4}.gbx-2 .gbx-am,.gbx-2 .gbx-wd{font-size:13.5px;line-height:1.35}.gbx-2 .gbx-wd em{font-style:normal;font-size:10.5px;font-weight:800;color:#fff;background:#C6395F;border-radius:999px;padding:2px 7px;white-space:nowrap}.gbx-2 li.on{background:linear-gradient(90deg,#FFF5F8,rgba(255,245,248,0))}@endif
@if ($gbxBands > 0 && $gbxCrit === '3').gbx-tabs{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding:2px 2px 10px;margin:0;border:0;min-width:0}.gbx-tabs label{flex:none;cursor:pointer}.gbx-tabs input{position:absolute;opacity:0;width:1px;height:1px;margin:0}.gbx-tabs label>span{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;border:1px solid #e3d9de;background:#fff;font-size:12.5px;font-weight:700;border-radius:12px;padding:8px 12px;min-height:44px;box-sizing:border-box}.gbx-tabs i{font-style:normal;font-size:9.5px;font-weight:800;color:#C6395F}.gbx-tabs input:checked+span{background:#2e8f62;border-color:#2e8f62;color:#fff}.gbx-tabs input:checked+span i{color:#fff}.gbx-tabs input:focus-visible+span{outline:2px solid #C6395F;outline-offset:2px}.gbx-tp{display:none}.gbx-tp.on{display:block}.gbx-3:has(input:checked) .gbx-tp{display:none}@for ($i = 0; $i < $gbxBands; $i++).gbx-3:has(input[value="{{ $i }}"]:checked) .gbx-tp[data-i="{{ $i }}"]{display:block}@endfor .gbx-tp .gbx-wd{margin:4px 2px 12px;font-size:14.5px;font-weight:700}.gbx-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.gbx-gc{display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px;min-width:0}.gbx-gc .gbx-t{width:72px;height:72px;border-radius:12px}.gbx-gn{font-size:11.5px;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}@endif
@media (max-width:600px){.gbx-pA{width:100vw;max-width:100vw;margin:auto 0 0;border-radius:18px 18px 0 0}.gbx-cp{width:100vw;max-width:100vw;max-height:85vh;margin:auto 0 0;border-radius:18px 18px 0 0}.gbx-2 li{grid-template-columns:28px minmax(0,1fr) auto;row-gap:2px}.gbx-2 .gbx-am{grid-column:2}.gbx-2 .gbx-wd{grid-column:2/4;grid-row:2}.gbx-2 .gbx-cn{grid-column:3;grid-row:1}.gbx-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
